def indep_plan(req):
    """Independent recomputation of per-flow benefit straight from JSON."""
    F={f['id']:f for f in req['flows']}
    caps=req['capacities']; warm=req['warmup']
    ben={}
    for fid,runs in req['offers'].items():
        f=F[fid]; kinds=f['kinds']; tmpl=bytes.fromhex(f['template']); H=len(kinds)
        N=len(f['path']); h=N-1
        per=(H-4-kinds.count('D'))*N
