        for r in runs:
            hdr=bytes.fromhex(r['header']); cnt=r['count']
            skip=min(left,cnt); left-=skip; cnt-=skip
            if cnt<=0: continue
            ks=[i for i,c in enumerate(kinds) if c=='K']
            if all(hdr[i]==tmpl[i] for i in ks) and hdr[kinds.index('Q')]<=7 and hdr[kinds.index('T')]>h:
